import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"泰","description":"焦氏易林注 - 泰","frontmatter":{"title":"泰","description":"焦氏易林注 - 泰"},"headers":[],"relativePath":"zh/classics/jiaoyilin/011.md","filePath":"zh/classics/jiaoyilin/011.md"}'),l={name:"zh/classics/jiaoyilin/011.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="泰" tabindex="-1">泰 <a class="header-anchor" href="#泰" aria-label="Permalink to “泰”">​</a></h1><h3 id="泰-1" tabindex="-1">泰 <a class="header-anchor" href="#泰-1" aria-label="Permalink to “泰”">​</a></h3><h3 id="泰之乾" tabindex="-1">泰之乾 <a class="header-anchor" href="#泰之乾" aria-label="Permalink to “泰之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>伯夷叔齊，貞廉之師。以德防患，憂禍不存。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《剝》。此用泰象。震為伯，坤殺，故曰伯夷。夷，滅也。伏艮為叔，巽為齊，故曰叔齊。</p><h3 id="泰之坤" tabindex="-1">泰之坤 <a class="header-anchor" href="#泰之坤" aria-label="Permalink to “泰之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>濟深難渡，濡我衣褲。五子善權，脫無他故。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>坤為水，故曰濟深、曰難渡、曰濡。坤為我、為衣褲。</p><h3 id="泰之屯" tabindex="-1">泰之屯 <a class="header-anchor" href="#泰之屯" aria-label="Permalink to “泰之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>倚立相望，適得道通。驅駕奔馳，比目同床。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>艮倚震立，艮望，正反艮，故曰相望。震為道、為通、為驅駕奔馳。艮為目，初至五爻正反艮相對，故曰比目。艮為床，坤眾，故曰同床。○得，依宋本，汲古作我。</p><h3 id="泰之蒙" tabindex="-1">泰之蒙 <a class="header-anchor" href="#泰之蒙" aria-label="Permalink to “泰之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>葛藟蒙棘，華不得實。讒佞為政，使恩壅塞。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《中孚》。</p><h3 id="泰之需" tabindex="-1">泰之需 <a class="header-anchor" href="#泰之需" aria-label="Permalink to “泰之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>四足無角，君子所服。南征述職，與福相得。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>此用《泰》象。震為足，卦數四，故曰四足。艮為角，艮伏，故無角。乾為君子，震為南、為徵，乾為福。○四足無角，依宋元本，汲古作&quot;四牡兼用&quot;。相得，依宋元本，汲古作同德。</p><h3 id="泰之訟" tabindex="-1">泰之訟 <a class="header-anchor" href="#泰之訟" aria-label="Permalink to “泰之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>踝踵足傷，左指病癰。失旅後時，利走不來。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《旅》，通《明夷》。震為足、為踝踵。坎為傷、為病癰。震為左，因明夷互震中互坎故有此象。○足，依汲古，宋元本作之，乃趾音之訛，然則足或為趾。</p><h3 id="泰之師" tabindex="-1">泰之師 <a class="header-anchor" href="#泰之師" aria-label="Permalink to “泰之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>春城夏國，生長之域。可以服食，保全家國。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>坤為城、為國，震為春，伏離為夏，故曰春城夏國。震為長生、為食，坤為家，震樂，故保全。○生長，汲古作長生，依宋元本。</p><h3 id="泰之比" tabindex="-1">泰之比 <a class="header-anchor" href="#泰之比" aria-label="Permalink to “泰之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>望驥不來，拘蹇為憂。雨驚我心，風撼我肌。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮為望，乾為驥，乾伏，故不來。坎為蹇、為憂、為雨、為心，坤為我、為風，艮為肌膚、為撼。○拘，宋元本作駒，依汲古。</p><h3 id="泰之小畜" tabindex="-1">泰之小畜 <a class="header-anchor" href="#泰之小畜" aria-label="Permalink to “泰之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>久客無床，思歸我鄉。雷雨滿盈，道不得通。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>巽為旅客、為床，兌毀折，故無床。伏坎為思，震為歸，坤為我、為鄉，震為雷，坎為雨，坤亦為水，故曰滿盈。艮為道，坎陷，故不通。○滿，從元本，宋本作涌，汲古作浸。</p><h3 id="泰之履" tabindex="-1">泰之履 <a class="header-anchor" href="#泰之履" aria-label="Permalink to “泰之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>方船備水，傍河燃火。積善有微，終身無禍。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。坤為方，震為船，坎為水。方，並也。《詩》&quot;方舟為梁&quot;是也。以船為梁，故曰備水。坤為河，艮為火，故曰傍河然火。坤為積，震為善，坤為身，艮為終，坤為禍。○汲古多&quot;天福吉昌，永得安康&quot;八字。方，從汲古，宋元本作舫。</p><h3 id="泰之泰" tabindex="-1">泰之泰 <a class="header-anchor" href="#泰之泰" aria-label="Permalink to “泰之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>求玉陳國，留連東域。須我王孫，四月來複。主君有德，蒙恩受福。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>坤為國，震為玉、為陳、為東，伏艮為流連、為須、為孫，乾為王，故曰王孫。兌為月，震為復，卦數四，故曰四月來複。震為主、為君，乾為德、為恩福。○求玉，依宋元本，汲古作有求。《左傳》有韓宣子求玉環於鄭事，茲雲陳國未詳。</p><h3 id="泰之否" tabindex="-1">泰之否 <a class="header-anchor" href="#泰之否" aria-label="Permalink to “泰之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>陟岵望母，役事未已。王政靡盬，不得相保。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>互艮為山、為望，坤為母，故曰陟岵望母。《爾雅釋山》：&quot;有草木曰岵&quot;。坤為役、為事，乾為王，坤為政，《詩魏風》：&quot;陟彼岵兮，瞻望母兮&quot;，又《唐風》&quot;王事靡盬&quot;，傳：盬，不攻致也。坤惡，故曰靡監。○靡，依汲古，與詩同，宋元作無，非。</p><h3 id="泰之同人" tabindex="-1">泰之同人 <a class="header-anchor" href="#泰之同人" aria-label="Permalink to “泰之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>多載重負，捐棄於野。予母誰子，但自勞苦。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>通《師》。坤為載負、為重、為野、為喪，故曰捐棄。坤為母，震為子，坎為勞苦。○三四句從宋本，汲古作&quot;王母離子，思勞自苦&quot;。重負，從宋元本，汲古作負重。</p><h3 id="泰之大有" tabindex="-1">泰之大有 <a class="header-anchor" href="#泰之大有" aria-label="Permalink to “泰之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>生直地乳，上皇大喜。賜我福祉，壽算無極。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>通《比》。坤為地，艮為乳。《洛書甄耀度》：政山左昆侖，西南為地乳。王勃《九成宮頌》：峰橫地乳。翟雲升釋地乳為醴泉，非。乾為帝、為皇，艮高，九五獨尊，故曰上皇。乾為大，兌為悅，故曰大喜。坤為我，乾為福祉。艮為壽，坤多，故曰壽算無極。○壽算，依汲古，宋元本作受命。直，依宋元本，汲古作值。汲古多&quot;賓於作命&quot;四字，依宋元本。</p><h3 id="泰之謙" tabindex="-1">泰之謙 <a class="header-anchor" href="#泰之謙" aria-label="Permalink to “泰之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>翕翕，隕墜山顛。滅我令名，長沒不全。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《離》。○隕墜山顛，依汲古，宋本元本作崩顛。全，依宋元，汲古作存、作稍墮。</p><h3 id="泰之豫" tabindex="-1">泰之豫 <a class="header-anchor" href="#泰之豫" aria-label="Permalink to “泰之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>東鄰嫁女，為王妃後。莊公築館，以尊王母。歸於京師，季薑悅喜。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《觀》。○悅喜，汲古本作喜悅，茲依宋元本。莊應為桓。</p><h3 id="泰之隨" tabindex="-1">泰之隨 <a class="header-anchor" href="#泰之隨" aria-label="Permalink to “泰之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>伯虎仲熊，德義淵閎。使布五穀，陰陽順序。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>震為伯，坎為仲，艮為熊虎。巽為谷，卦數五，故曰五穀。</p><h3 id="泰之蠱" tabindex="-1">泰之蠱 <a class="header-anchor" href="#泰之蠱" aria-label="Permalink to “泰之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>敏捷勁疾，如猿升木。彤弓雖調，終不能獲。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>巽風為敏捷、為木。艮為猿，在巽上，故曰升木。互大坎為弓，震為玄黃，故曰彤弓。</p><h3 id="泰之臨" tabindex="-1">泰之臨 <a class="header-anchor" href="#泰之臨" aria-label="Permalink to “泰之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>舉袂覆目，不見日月。衣裘簟席，就長夜室。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《隨》。○震袂證，可解《歸妹》。</p><h3 id="泰之觀" tabindex="-1">泰之觀 <a class="header-anchor" href="#泰之觀" aria-label="Permalink to “泰之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>忍醜少羞，無面有頭。耗減寡虛，日以削消。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>坤為醜、為羞，艮止為忍，又為面。巽為廣顙，艮在下，巽伏，故無面，廣顙在上，故有頭。坤為耗、為虛，巽為寡，伏乾為日，坤為消。○艮為面證。三四句依汲古，宋元本作&quot;虛日以弊，消寡耗減&quot;。</p><h3 id="泰之噬嗑" tabindex="-1">泰之噬嗑 <a class="header-anchor" href="#泰之噬嗑" aria-label="Permalink to “泰之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>涸陰冱寒，常冰不溫。凌人惰怠，雹大為災。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>坎為陰寒、為冰，離為溫，居坎上，故不溫。震為人、為凌，故曰凌人。艮止，故曰怠。離為災，坎為雹，言冬不藏冰，夏致雹災。○涸，依宋元本，汲古作固。凌，依元本，宋本訛令。雹大，依宋元本，汲古訛庖大，按：《周禮天官》有凌人，鄭雲：凌，冰室也。引豳風&quot;納於凌陰&quot;為證。凌人藏冰出冰，正以宣泄寒暑，否則陰陽不調，而冰雹為災。情，依《否》之《蹇》校，各本皆作墮。</p><h3 id="泰之賁" tabindex="-1">泰之賁 <a class="header-anchor" href="#泰之賁" aria-label="Permalink to “泰之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>夏麥麩，霜擊其芒。疾君敗國，使民夭傷。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>離為夏，震為麥、為麩，坎為芒、為霜，艮手為擊，故霜擊其芒。坎為疾，震為君，艮為國，坎為敗、為民，艮為少，伏兌折，故夭傷。○，從宋本，汲古訛曲。震為君證。</p><h3 id="泰之剝" tabindex="-1">泰之剝 <a class="header-anchor" href="#泰之剝" aria-label="Permalink to “泰之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>淵涸龍憂，箕子為奴。乾叔隕命，殷破其家。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>坤為淵，艮火在中，故涸。震為龍，震覆，故憂。又坤亦為憂。《萃初六》雲&quot;勿恤&quot;，《升彖》雲&quot;勿恤&quot;，以坤為恤，是其證。震為箕子，艮為奴，上震覆為艮，故曰箕子為奴。艮為叔、為求，故曰乾叔，殷比乾也。坤死，故曰殞命。殷，子姓，震為子，震覆，故曰殷破其家。艮為家也。《明夷彖傳》雲：&quot;箕子以之&quot;，由此可證箕子指震。○家，音姑。乾叔，宋元本皆訛午叔。</p><h3 id="泰之復" tabindex="-1">泰之復 <a class="header-anchor" href="#泰之復" aria-label="Permalink to “泰之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>跛踦相隨，日暮牛罷。陵遲後旅，失利亡雌。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>震為行，坤退，故跛踦。坤為夜，故曰暮。為牛、為役，故罷。震為後、為旅，巽為利，巽伏，故失利。坤為雌、為亡。</p><h3 id="泰之無妄" tabindex="-1">泰之無妄 <a class="header-anchor" href="#泰之無妄" aria-label="Permalink to “泰之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>桑之將落，隕其黃葉。失勢傾側，如無所立。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>《詩衛風》：&quot;桑之落矣，其黃而隕&quot;。震為桑，巽為隕落，震為黃、為葉、為立，巽為傾，故曰失勢傾側，如無立也。○之，從宋元本，汲古本作方，非。側，依宋元本，汲古作倒。</p><h3 id="泰之大畜" tabindex="-1">泰之大畜 <a class="header-anchor" href="#泰之大畜" aria-label="Permalink to “泰之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>生長以時，長育根本。陰陽和德，歲樂無憂。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>震為生長，艮為時，震為根荄，二五相應與，故曰陰陽和德。和，合也。震為歲、為樂。○和德，從宋元本，汲古作相和。</p><h3 id="泰之頤" tabindex="-1">泰之頤 <a class="header-anchor" href="#泰之頤" aria-label="Permalink to “泰之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>童女無夫，未有配合。陰陽不和，空坐獨宿。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>伏巽為童女。震為夫，坤寡，故無夫。上下卦皆男象，故未有配合，故不和。艮為坐、為宿，坤為寡、為夜，故曰空坐獨宿。○夫，從宋元本，汲古作室，非。按：伏兌為少女，童似為兌象，然曰無夫，震為夫，故知童女指巽，《大過》固以巽為女妻也。配合，依汲古，宋元本作匹配。</p><h3 id="泰之大過" tabindex="-1">泰之大過 <a class="header-anchor" href="#泰之大過" aria-label="Permalink to “泰之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>春令原有，仁德不周。三聖攸同，周國茂興。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>通《頤》。震為春，巽為命，故曰春令。古者霜降申憲，立春息刑，故曰原有。震為仁、為周，震伏，故不周，震數三，乾為聖，故曰三聖。坤為國。○不周，依汲古，與宥韻，宋元本作不合，與宥不韻。</p><h3 id="泰之坎" tabindex="-1">泰之坎 <a class="header-anchor" href="#泰之坎" aria-label="Permalink to “泰之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>金精躍怒，帶劍過午。兩虎相距，雖驚無咎。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>坎水為金精。震為躍怒，艮為劍，納丙，故曰過午。艮為虎，正覆艮，故曰兩虎相距。震為驚。○距，依宋元本，汲古作妒，非。白虎，西方宿，故曰金精。</p><h3 id="泰之離" tabindex="-1">泰之離 <a class="header-anchor" href="#泰之離" aria-label="Permalink to “泰之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>危坐至暮，請求不得。膏澤不降，政戾民忒。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《頤》，離中爻亦伏頤，伏頤，故語同。</p><h3 id="泰之咸" tabindex="-1">泰之咸 <a class="header-anchor" href="#泰之咸" aria-label="Permalink to “泰之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>老楊日衰，條多枯枝。爵級不進，日下摧頹。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《訟》。</p><h3 id="泰之恒" tabindex="-1">泰之恒 <a class="header-anchor" href="#泰之恒" aria-label="Permalink to “泰之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>蔡侯適楚，留連江濱。逾曰厯月，思其後君。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>巽為蔡，震為楚，乾為江河、為日。兌為月，乾為君。○濱，從宋元本，汲古等本作湖，非。後君，從汲古，與濱協，宋元本作君後，以兌為月，與《恆彖傳》同。《左傳》&quot;蔡侯朝楚，楚相囊瓦欲其羔裘而不肯獻，遂留楚二年&quot;。</p><h3 id="泰之遯" tabindex="-1">泰之遯 <a class="header-anchor" href="#泰之遯" aria-label="Permalink to “泰之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>右撫劍佩，左援鉤帶。凶訟不止，相與爭戾，失利市肆。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>艮為劍、為鉤，巽為帶，乾為言，兌口與乾言反，故曰訟、曰爭。巽為利市，風隕故失。○佩，依汲古，宋元本作頭，若依宋本則下句當為帶鉤，與頭協，然各本皆作鉤帶，無如何也。鉤亦兵器。</p><h3 id="泰之大壯" tabindex="-1">泰之大壯 <a class="header-anchor" href="#泰之大壯" aria-label="Permalink to “泰之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>水流趨下，遠至東海。求我所有，買鮪與鯉。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>詳《訟》之《比》。○與，從宋元本，汲古作得，非。此全用對象，故與《比》同詞。</p><h3 id="泰之晉" tabindex="-1">泰之晉 <a class="header-anchor" href="#泰之晉" aria-label="Permalink to “泰之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>登幾上輿，駕駟南游。合從散橫，燕齊以強。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《否》，齊皆作秦，依《屯》之《否》宋元本校，散衡與秦不利，故知秦非。</p><h3 id="泰之明夷" tabindex="-1">泰之明夷 <a class="header-anchor" href="#泰之明夷" aria-label="Permalink to “泰之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>求兔得獐，過其所望。歡以相迎，高位夷傷。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為兔，艮為獐，艮覆，故得獐。離目為望，震在上，故曰過望。震為歡，伏巽為高，艮為位，艮覆，故夷傷。</p><h3 id="泰之家人" tabindex="-1">泰之家人 <a class="header-anchor" href="#泰之家人" aria-label="Permalink to “泰之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>過時不歸，道遠且迷。旅人心悲，使我徘徊。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>震為時、為歸，震伏，故不歸。又震巽相反覆，震究為巽，故曰過時。震為道，坎伏，故迷。巽為商旅。坎為心、為悲。</p><h3 id="泰之睽" tabindex="-1">泰之睽 <a class="header-anchor" href="#泰之睽" aria-label="Permalink to “泰之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>魂孤無室，御宿舍食。盜張民潰，見敵失內。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>坎為魂、為孤、為室，坎隱，故無室。兌為食，坎為宿、為盜、為民。○次句宋元本作&quot;銜指含食&quot;，汲古本作御宿舍食。潰、內，亦依汲古，宋元本作饋、作肉。失內者，失其妻室也。《左傳僖十七年》：&quot;齊侯好內&quot;，是內為妻妾也。</p><h3 id="泰之蹇" tabindex="-1">泰之蹇 <a class="header-anchor" href="#泰之蹇" aria-label="Permalink to “泰之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>居如轉丸，危不得安。東西不寧，動生憂患。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>坎為丸，坎險，故曰危、曰不寧。離東坎西，坎為憂患。○離東坎西證。艮為居，上坎，故曰居如轉丸。</p><h3 id="泰之解" tabindex="-1">泰之解 <a class="header-anchor" href="#泰之解" aria-label="Permalink to “泰之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>坤厚地德，庶物蕃息。平康正直，以綏百福。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>此用《泰》象。坤為厚、為庶物。震為蕃息，震大塗，故曰平康正直。乾為百福。</p><h3 id="泰之損" tabindex="-1">泰之損 <a class="header-anchor" href="#泰之損" aria-label="Permalink to “泰之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>樹蔽牡荊，生蘙山旁。讎敵背憎，孰肯相迎。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>震為樹、為荊，震陽卦，故曰牡荊。震為生、為蘙。艮為山，二至上正反兩艮震相背，故曰背憎、曰讎敵，相背故不相迎。○樹蘙，依《未濟》之《姤》校，各本皆訛作挒、作賢。山旁，依元本，宋本作山傍，汲古訛止侮。末多&quot;上下有眚&quot;四字。</p><h3 id="泰之益" tabindex="-1">泰之益 <a class="header-anchor" href="#泰之益" aria-label="Permalink to “泰之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>鳳凰銜書，賜我玄圭，封為晉侯。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>坤為鳳、為書，震口為銜、為玄、為圭。艮為封。震為晉、為諸侯。○汲古作玄圭賜我，依宋元本。</p><h3 id="泰之夬" tabindex="-1">泰之夬 <a class="header-anchor" href="#泰之夬" aria-label="Permalink to “泰之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>作凶不善，相牽入井。溺陷辜罪，禍至憂有。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>兌毀折故曰凶。又通《剝》。下坤為凶，艮手為牽，坤為淵、為井、為辜罪、為憂禍，為水，故溺。○坤為憂證。至、有，依宋本，汲古作生、滋。</p><h3 id="泰之姤" tabindex="-1">泰之姤 <a class="header-anchor" href="#泰之姤" aria-label="Permalink to “泰之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>悲鳴北行，失其長兄。伯仲不幸，骸骨散亡。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。震為鳴，坤為悲、為北、為失。震為長兄、為伯，震伏故失。兌為骸骨，兌覆風散，故曰散亡。○散亡，依宋元本，汲古作敗亡。坤為北證。</p><h3 id="泰之萃" tabindex="-1">泰之萃 <a class="header-anchor" href="#泰之萃" aria-label="Permalink to “泰之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>羔衣豹裘，高易我宇，君子維好。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>兌為羔。互艮為豹。坤為衣裘。巽為高。艮為宇、為君子。○宇，依汲古，宋元作家。好，依宋元，汲古作新。兌為羔證，可見《說卦》羔非訛字。</p><h3 id="泰之升" tabindex="-1">泰之升 <a class="header-anchor" href="#泰之升" aria-label="Permalink to “泰之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>日中為市，各抱所有。交易貨貲，貪珠懷寶，心悅歡喜。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>通《無妄》。巽為市，乾為日，艮手為抱，巽為交易，乾為貨貲，震為珠玉、為悅喜。</p><h3 id="泰之困" tabindex="-1">泰之困 <a class="header-anchor" href="#泰之困" aria-label="Permalink to “泰之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>振急絕理，恆陽不雨。物病焦乾，華實無有。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>通《賁》。下離火，艮又為火，故曰暘日不雨。互坎為雨、為病，離火為焦，乾艮為果、為實，兌為華。○兌為華證。《大過九五》即以兌為華。又按：焦、京皆以《無妄》為大旱之卦，亦以艮火互大離為說，自艮火象失傳，虞翻即不解京義。恆，依汲古，宋元作常，陽當作暘。</p><h3 id="泰之井" tabindex="-1">泰之井 <a class="header-anchor" href="#泰之井" aria-label="Permalink to “泰之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>狐狢載剝，徙溫厚蓐。寒棘為疾，有所不足。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>坎為狐狢，伏艮為手、為剝。巽為茅蓐。坎為寒、為棘、為疾。震為足，震伏，故不足。○厚、有，依宋元本，汲古作萃、作何。又徙汲古作凌，依宋元本。</p><h3 id="泰之革" tabindex="-1">泰之革 <a class="header-anchor" href="#泰之革" aria-label="Permalink to “泰之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>履踐危難，脫執去患。入福喜門，見誨大君。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。震為履踐，坎險，故曰危難。震為脫、為去，坎陷，故曰執，坎憂，故曰患。艮為門，震為福喜。巽為入。乾為大君，震為誨。</p><h3 id="泰之鼎" tabindex="-1">泰之鼎 <a class="header-anchor" href="#泰之鼎" aria-label="Permalink to “泰之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>四亂不安，東西為患。艮止我足，無出國域。乃得全完，賴其生福。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。坤為亂，震數四，故曰四亂。震東坎西，坎為憂，故曰東西為患。震為足，艮止。坤為國，艮為域，上坎陷故不出。震為福，言見險能止，故得安全而生福也。全用對象。○坎西之證。</p><h3 id="泰之震" tabindex="-1">泰之震 <a class="header-anchor" href="#泰之震" aria-label="Permalink to “泰之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>南國少子，材略美好。求我長女，賤薄不與。反得醜惡，後乃大悔。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《漸》。</p><h3 id="泰之艮" tabindex="-1">泰之艮 <a class="header-anchor" href="#泰之艮" aria-label="Permalink to “泰之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>妄怒失理，陽孤無輔。物病焦枯，年飢於黍。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>互震為怒，坎為失，陽止於上，故曰孤、曰無輔。坎為病，艮為火，故物病焦枯。震為黍、為年，焦枯故飢。○艮為孤，《易林》凡遇六子皆有孤寡象，不祇巽為寡也。</p><h3 id="泰之漸" tabindex="-1">泰之漸 <a class="header-anchor" href="#泰之漸" aria-label="Permalink to “泰之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>倬然遠咎，闢患害早。田獲三狐，巨貝為寶。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>風散，故倬然遠咎。坎為患害，巽出險故能闢患。艮為狐，數三，故曰三狐。坎為獲，艮為貝，巽為高、為長，故曰巨貝。○艮為貝，《易》震貝得解。巨貝，從汲古，宋元作見民。見，貝之訛。民，巨之訛。</p><h3 id="泰之歸妹" tabindex="-1">泰之歸妹 <a class="header-anchor" href="#泰之歸妹" aria-label="Permalink to “泰之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>逐鹿山巔，利去我西。維邪南北，無所不得。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>震為鹿、為逐，艮覆，故至山顛。兌為西，離南坎北。維邪，呼聲。○維邪，依宋元本，汲古等本作雖邪，疑訛。按：《史記滑稽傳》：&quot;污邪滿車&quot;，疑與此義同。污維音亦通。史記註：污邪，下田也。似非。按：《爾雅釋詁》：&quot;伊，維也&quot;，註：發語辭。《淮南子》：&quot;今夫舉大木者前呼邪許，後亦應之&quot;，此舉重勸力之歌也，然則維邪者，呼聲也。《歸妹》上震為言，下兌為口，故曰維邪。由是推《史記》之污邪與《淮南》之邪許同，而非下田。</p><h3 id="泰之豐" tabindex="-1">泰之豐 <a class="header-anchor" href="#泰之豐" aria-label="Permalink to “泰之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>龍蛇所眾，大水來處。滑滑沛沛，使我無賴。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>震龍巽蛇，互大坎，故曰聚、曰大水、曰滑滑沛沛。○沛沛，宋元本作泲泲，依汲古。</p><h3 id="泰之旅" tabindex="-1">泰之旅 <a class="header-anchor" href="#泰之旅" aria-label="Permalink to “泰之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>從風吹火，牽麒驥尾。易為功力，因摧受福。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>巽為風，兌口為吹，離在上，故曰吹火。艮為尾、為牽，伏震為馬。兌為摧折，震為福。○功力，從宋本，汲古作之功，非。</p><h3 id="泰之巽" tabindex="-1">泰之巽 <a class="header-anchor" href="#泰之巽" aria-label="Permalink to “泰之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>澤狗水鳧，難畜少雛。不為家饒，心其亟逋。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>通《震》。互艮為狗，兌為澤，故曰澤狗。《說文》：&quot;獺如小狗，水居食魚是也&quot;。震為鳧，坎水，故曰水鳧。二者皆野物，故難畜。震為子、為雛，震伏，故曰少雛。互艮為家，坎為心，震往，故曰逋，言澤狗水鳧不為家畜，時時欲逃也。亟逋，依汲古，宋本作函憂。憂饒古亦葉。</p><h3 id="泰之兌" tabindex="-1">泰之兌 <a class="header-anchor" href="#泰之兌" aria-label="Permalink to “泰之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>水壞我里，東流為海。龜鳧驩囂，不見慈母。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>通《艮》為里，互坎為水，互震為東，兌為海，艮為龜，震為鳧、為樂，故曰驩囂。巽為母，坎伏故不見。</p><h3 id="泰之渙" tabindex="-1">泰之渙 <a class="header-anchor" href="#泰之渙" aria-label="Permalink to “泰之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>褰衣涉河，水深漬罷。賴幸舟子，濟脫無他。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>首二句依《訟》之《萃》校，宋元本作&quot;褰衣涉行，水深漬多&quot;，汲古作&quot;深漬請罷，非子作者&quot;，尤非。罷，音婆。</p><h3 id="泰之節" tabindex="-1">泰之節 <a class="header-anchor" href="#泰之節" aria-label="Permalink to “泰之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>龜厭江海，陸行不止。自令枯槁，失其都市。憂悔為咎，亦無及己。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>艮為龜，兌為河海，震為行，艮為陸，互大離為枯槁，巽為市，坎為憂。○悔為，從宋本，汲古作害無。厭作戢，皆非。艮為龜證。末句依宋元，汲古無。</p><h3 id="泰之中孚" tabindex="-1">泰之中孚 <a class="header-anchor" href="#泰之中孚" aria-label="Permalink to “泰之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>同本異葉，樂仁政德。東鄰慕義，來興我國。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>互大離為東鄰。艮為國。○政，依宋本，汲古作正。</p><h3 id="泰之小過" tabindex="-1">泰之小過 <a class="header-anchor" href="#泰之小過" aria-label="Permalink to “泰之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>桃李花實，纍纍日息。長大成熟，甘美可食，為我利福。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>震為桃李，兌為花，艮為實、為成，巽為長，兌為食，震為福，巽為利。</p><h3 id="泰之既濟" tabindex="-1">泰之既濟 <a class="header-anchor" href="#泰之既濟" aria-label="Permalink to “泰之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>重瞳四乳，聰明順理。無隱不形，微見千里。災害不作，君子集聚。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此用《泰》象。伏艮為目，巽為重，故曰重瞳。艮為乳，巽數四，故曰四乳。艮明坤順，巽伏故隱。兌為見，坤為千里、為災。乾為福故不災。艮為君子，坤為積聚。文王四乳，舜目重瞳，見《淮南子》。</p><h3 id="泰之未濟" tabindex="-1">泰之未濟 <a class="header-anchor" href="#泰之未濟" aria-label="Permalink to “泰之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>實沈參墟，以義討尤。次止結盟，以成霸功。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>按：《左傳昭元年》：&quot;遷實沈於大夏，主參。&quot;故參為晉星。泰伏艮，艮為星，故曰實沈、曰參，而實沈與參皆晉墟。震為晉也。皆用《泰》象。文意似指晉文伐楚事。止，首止，僖五年齊侯會諸侯於首止。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
